PigeonInternalCodecSerializer::PigeonInternalCodecSerializer() {}

EncodableValue PigeonInternalCodecSerializer::ReadValueOfType(
  uint8_t type,
  ::flutter::ByteStreamReader* stream) const {
  switch (type) {
    case 129: {
        return CustomEncodableValue(RecordPutRequest::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 130: {
        return CustomEncodableValue(RecordData::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 131: {
        return CustomEncodableValue(CollectionData::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 132: {
        return CustomEncodableValue(CollectionsWatchToken::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 133: {
        return CustomEncodableValue(CollectionWatchToken::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 134: {
        return CustomEncodableValue(RecordWatchToken::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 135: {
        return CustomEncodableValue(PreferenceWatchToken::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    default:
      return ::flutter::StandardCodecSerializer::ReadValueOfType(type, stream);
    }
}

void PigeonInternalCodecSerializer::WriteValue(
  const EncodableValue& value,
  ::flutter::ByteStreamWriter* stream) const {
  if (const CustomEncodableValue* custom_value = std::get_if<CustomEncodableValue>(&value)) {
    if (custom_value->type() == typeid(RecordPutRequest)) {
      stream->WriteByte(129);
      WriteValue(EncodableValue(std::any_cast<RecordPutRequest>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(RecordData)) {
      stream->WriteByte(130);
      WriteValue(EncodableValue(std::any_cast<RecordData>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(CollectionData)) {
      stream->WriteByte(131);
      WriteValue(EncodableValue(std::any_cast<CollectionData>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(CollectionsWatchToken)) {
      stream->WriteByte(132);
      WriteValue(EncodableValue(std::any_cast<CollectionsWatchToken>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(CollectionWatchToken)) {
      stream->WriteByte(133);
      WriteValue(EncodableValue(std::any_cast<CollectionWatchToken>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(RecordWatchToken)) {
      stream->WriteByte(134);
      WriteValue(EncodableValue(std::any_cast<RecordWatchToken>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(PreferenceWatchToken)) {
      stream->WriteByte(135);
      WriteValue(EncodableValue(std::any_cast<PreferenceWatchToken>(*custom_value).ToEncodableList()), stream);
      return;
    }
  }
  ::flutter::StandardCodecSerializer::WriteValue(value, stream);
}

/// The codec used by SharedDatabaseApi.
const ::flutter::StandardMessageCodec& SharedDatabaseApi::GetCodec() {
  return ::flutter::StandardMessageCodec::GetInstance(&PigeonInternalCodecSerializer::GetInstance());
}

